begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temp table im_fx(k text primary key,id uuid,v jsonb);
grant all on im_fx to authenticated;
insert into im_fx(k,id)select k,gen_random_uuid()from unnest(array['actor','other','session','other_session','study','action','correction','void','document','cancel','cancel_study'])k;
create function pg_temp.im_id(key text)returns uuid language sql as $$select id from im_fx where k=$1$$;
create function pg_temp.im_values()returns jsonb language sql as $$select v from im_fx where k='values'$$;
insert into auth.users(id,email,raw_user_meta_data)select id,'imaging-'||id||'@example.test','{}'from im_fx where k in('actor','other');
update profiles set is_active=true,full_name='Synthetic imaging staff'where id in(pg_temp.im_id('actor'),pg_temp.im_id('other'));
insert into user_roles(user_id,role)values(pg_temp.im_id('actor'),'STAFF'),(pg_temp.im_id('other'),'STAFF')on conflict do nothing;
insert into auth.sessions(id,user_id,created_at,updated_at)values(pg_temp.im_id('session'),pg_temp.im_id('actor'),now(),now()),(pg_temp.im_id('other_session'),pg_temp.im_id('other'),now(),now());
select ok(relrowsecurity and not has_table_privilege('authenticated',oid,'SELECT')and not has_table_privilege('authenticated',oid,'INSERT')and not has_table_privilege('service_role',oid,'SELECT'),relname||' is private')from pg_class where relnamespace='public'::regnamespace and relname in('imaging_studies','imaging_study_revisions','imaging_study_actions');
select ok(has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' exposes only its staff RPC')from pg_proc where pronamespace='public'::regnamespace and proname in('read_imaging_study','list_imaging_studies','list_imaging_history','save_imaging_study','recover_imaging_action','cancel_imaging_action');
select ok(not has_function_privilege('authenticated',oid,'EXECUTE')and not has_function_privilege('anon',oid,'EXECUTE')and not has_function_privilege('service_role',oid,'EXECUTE'),proname||' remains owner-only')from pg_proc where pronamespace='public'::regnamespace and proname in('imaging_validate','imaging_detail','imaging_report_available','imaging_root_guard','record_request_inventory','record_request_inventory_before_imaging');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.im_id('actor'),'session_id',pg_temp.im_id('session'))::text,true);
set local role authenticated;
insert into im_fx(k,id)select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Imaging','+13035555351','imaging-sql@example.test','EMAIL',null,null);
insert into im_fx(k,id)select 'pet',id from save_patient(null,pg_temp.im_id('client'),null,'Synthetic Imaging','Dog','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into im_fx(k,id)select 'other_pet',id from save_patient(null,pg_temp.im_id('client'),null,'Other Imaging','Cat','Mixed',null,'unknown','','unknown','unknown','',null,null);
insert into im_fx(k,id)select 'encounter',id from save_clinical_encounter(null,pg_temp.im_id('pet'),null,now(),'clinic','Synthetic clinic','Original history','Original exam','Original assessment','Original plan');
insert into im_fx(k,id)select 'other_encounter',id from save_clinical_encounter(null,pg_temp.im_id('other_pet'),null,now(),'clinic','Synthetic clinic','','','','');
insert into im_fx(k,v)values('values',jsonb_build_object('account_label','Synthetic practice','vendor_patient_id','SYNTH-001','external_study_id','SYNTH-STUDY-001','accession','SYNTH-ACC-001','study_date','2026-10-16','modality','DX','description','Synthetic thorax study','body_region','Thorax','viewer_url','https://pacs5.vetrocket.net/view.html?link=SYNTHETIC_ONLY','encounter_id',pg_temp.im_id('encounter'),'encounter_version',1,'document_id',null,'document_version',null,'identity_verified',true,'review_note','Confirmed source patient ID, species and study date against this patient.'));
select is(list_imaging_studies(auth.uid(),pg_temp.im_id('pet'))->'items','[]'::jsonb,'Initially no imaging');
select throws_ok($$select list_imaging_studies(pg_temp.im_id('other'),pg_temp.im_id('pet'))$$,'42501',null,'Actor spoof rejected');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"identity_verified":false}','')$$,'23514',null,'Explicit patient review required');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"extra":"field"}','')$$,'23514',null,'Unknown fields rejected');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"study_date":"2026-02-30"}','')$$,'23514',null,'Invalid calendar date rejected');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"encounter_version":null}','')$$,'23514',null,'Source ID and version required together');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||jsonb_build_object('encounter_id',pg_temp.im_id('other_encounter')),'')$$,'23514',null,'Wrong patient encounter rejected');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"encounter_version":2}','')$$,'PT409',null,'Stale encounter rejected');
select throws_ok(format('select save_imaging_study(auth.uid(),gen_random_uuid(),%L,%L,null,''record'',pg_temp.im_values()||jsonb_build_object(''viewer_url'',%L),'''')',pg_temp.im_id('study'),pg_temp.im_id('pet'),url),'23514',null,'Unsafe viewer rejected: '||label)
from(values('http://pacs5.vetrocket.net/view.html?link=SYNTHETIC_ONLY','HTTP'),('https://pacs5.vetrocket.net.evil.test/view.html?link=SYNTHETIC_ONLY','suffix'),('https://user@pacs5.vetrocket.net/view.html?link=SYNTHETIC_ONLY','userinfo'),('https://pacs5.vetrocket.net:8443/view.html?link=SYNTHETIC_ONLY','port'),('https://127.0.0.1/view.html?link=SYNTHETIC_ONLY','loopback'),('javascript:alert(1)','script'),('https://pacs5.vetrocket.net/other?link=SYNTHETIC_ONLY','path'),('https://pacs5.vetrocket.net/view.html?link=SYNTHETIC_ONLY&token=secret','extra query'),('https://pacs5.vetrocket.net/view.html?link=SYNTHETIC_ONLY#fragment','fragment'))u(url,label);
insert into im_fx(k,v)select 'saved',save_imaging_study(auth.uid(),pg_temp.im_id('action'),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values(),'');
select is((select v#>>'{study,version}'from im_fx where k='saved'),'1','First version recorded');
select is((select v->'report_available'from im_fx where k='saved'),'null'::jsonb,'No report means no availability claim');
select is(save_imaging_study(auth.uid(),pg_temp.im_id('action'),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values(),''),(select v from im_fx where k='saved'),'Duplicate exact UUID recovers receipt');
select is(recover_imaging_action(auth.uid(),pg_temp.im_id('action'),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values(),''),(select v from im_fx where k='saved'),'Read-only recovery returns original receipt');
select is(recover_imaging_action(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values(),''),null::jsonb,'Uncommitted action recovery returns null');
select throws_ok($$select recover_imaging_action(auth.uid(),pg_temp.im_id('action'),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"description":"Changed"}','')$$,'23505',null,'Altered action intent rejected');
select is(read_imaging_study(auth.uid(),pg_temp.im_id('other_pet'),pg_temp.im_id('study')),null::jsonb,'Wrong-patient read returns no study');
select is(cancel_imaging_action(auth.uid(),pg_temp.im_id('action'),pg_temp.im_id('study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values(),'')->'receipt',(select v from im_fx where k='saved'),'Cancellation recovers an already committed save');
select is(cancel_imaging_action(auth.uid(),pg_temp.im_id('cancel'),pg_temp.im_id('cancel_study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"external_study_id":"CANCELLED"}','')->'cancelled','true'::jsonb,'Uncommitted action durably cancelled');
select is(cancel_imaging_action(auth.uid(),pg_temp.im_id('cancel'),pg_temp.im_id('cancel_study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"external_study_id":"CANCELLED"}','')->'cancelled','true'::jsonb,'Cancellation itself is idempotent');
select throws_ok($$select save_imaging_study(auth.uid(),pg_temp.im_id('cancel'),pg_temp.im_id('cancel_study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"external_study_id":"CANCELLED"}','')$$,'PT409',null,'Late original write cannot pass durable cancellation');
select is(read_imaging_study(auth.uid(),pg_temp.im_id('pet'),pg_temp.im_id('cancel_study')),null::jsonb,'Cancelled request creates no study');
select throws_ok($$select cancel_imaging_action(auth.uid(),pg_temp.im_id('cancel'),pg_temp.im_id('cancel_study'),pg_temp.im_id('pet'),null,'record',pg_temp.im_values(),'')$$,'23505',null,'Cancellation cannot change original intent');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),gen_random_uuid(),pg_temp.im_id('pet'),null,'record',pg_temp.im_values()||'{"vendor_patient_id":"DIFFERENT"}','')$$,'23505',null,'External study uniqueness also rejects a different vendor patient identity');

select is(list_imaging_history(auth.uid(),pg_temp.im_id('other_pet'),pg_temp.im_id('study'))->'items','[]'::jsonb,'Wrong-patient history empty');
select is(jsonb_array_length(list_imaging_studies(auth.uid(),pg_temp.im_id('pet'))->'items'),1,'Patient list contains study');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),gen_random_uuid(),pg_temp.im_id('other_pet'),null,'record',pg_temp.im_values()||'{"encounter_id":null,"encounter_version":null}','')$$,'23514',null,'External patient identity cannot be attached to a second patient');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),2,'correct',pg_temp.im_values(),'Stale review')$$,'PT409',null,'Stale correction rejected');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),1,'correct',pg_temp.im_values(),'')$$,'23514',null,'Correction reason required');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('other_pet'),1,'void',null,'Wrong patient')$$,'23514',null,'Wrong-patient void rejected');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),1,'correct',pg_temp.im_values()||'{"vendor_patient_id":"OTHER"}','Change identity')$$,'23514',null,'External patient identity immutable');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),1,'correct',pg_temp.im_values()||'{"account_label":"OTHER"}','Change account')$$,'23514',null,'Account identity immutable');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),1,'correct',pg_temp.im_values()||'{"external_study_id":"OTHER"}','Change study')$$,'23514',null,'Study identity immutable');
reset role;
-- Existing private document pipeline owns report storage; synthetic object metadata only in this rollback transaction.
insert into patient_documents(id,pet_id,encounter_id,file_name,file_path,mime_type,file_size,category,source,document_date,visibility,status,created_by)
values(pg_temp.im_id('document'),pg_temp.im_id('pet'),pg_temp.im_id('encounter'),'synthetic-report.pdf','synthetic/imaging-report.pdf','application/pdf',100,'medical_record','Synthetic VetRocket','2026-10-16','internal','uploading',pg_temp.im_id('actor'));
insert into storage.objects(bucket_id,name,metadata)select 'patient-documents',file_path,'{"size":100,"mimetype":"application/pdf"}'::jsonb from patient_documents where id=pg_temp.im_id('document');
update patient_documents set status='ready'where id=pg_temp.im_id('document');
update im_fx set v=v||jsonb_build_object('document_id',pg_temp.im_id('document'),'document_version',(select version from patient_documents where id=pg_temp.im_id('document')))where k='values';
set local role authenticated;
insert into im_fx(k,v)select 'corrected',save_imaging_study(auth.uid(),pg_temp.im_id('correction'),pg_temp.im_id('study'),pg_temp.im_id('pet'),1,'correct',pg_temp.im_values()||'{"description":"Synthetic corrected thorax"}','Attach reviewed report');
select is((select v#>>'{study,version}'from im_fx where k='corrected'),'2','Correction advances exactly one version');
select is((select v->'report_available'from im_fx where k='corrected'),'true'::jsonb,'Current PDF available');
select is(jsonb_array_length(list_imaging_history(auth.uid(),pg_temp.im_id('pet'),pg_temp.im_id('study'))->'items'),2,'History retains both versions');
select is(list_imaging_history(auth.uid(),pg_temp.im_id('pet'),pg_temp.im_id('study'),2)#>>'{items,0,snapshot,values,description}','Synthetic thorax study','Original study metadata retained');
select is((select version from clinical_encounters where id=pg_temp.im_id('encounter')),1,'Study association never changes encounter version');
select is((select subjective from clinical_encounters where id=pg_temp.im_id('encounter')),'Original history','Signed/unsigned SOAP untouched');
reset role;
select ok(not (record_request_inventory(pg_temp.im_id('pet'))::text like '%SYNTHETIC_ONLY%'),'Complete records never expose viewer bearer link');
select ok(exists(select 1 from jsonb_array_elements(record_request_inventory(pg_temp.im_id('pet'))->'exclusions')x where x->>'family'='imaging_study_ids'and x->>'id'=pg_temp.im_id('study')::text),'Complete records disclose imaging omission');
update patient_documents set status='void',void_reason='Synthetic void test'where id=pg_temp.im_id('document');
set local role authenticated;
select is(read_imaging_study(auth.uid(),pg_temp.im_id('pet'),pg_temp.im_id('study'))->'report_available','false'::jsonb,'Voided PDF disables current availability');
select is(recover_imaging_action(auth.uid(),pg_temp.im_id('correction'),pg_temp.im_id('study'),pg_temp.im_id('pet'),1,'correct',pg_temp.im_values()||'{"description":"Synthetic corrected thorax"}','Attach reviewed report')#>>'{study,version}','2','Recovery retains original commit despite later source change');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),2,'correct',pg_temp.im_values(),'Retain invalid source')$$,'PT409',null,'Voided PDF cannot be used in correction');
select is(save_imaging_study(auth.uid(),pg_temp.im_id('void'),pg_temp.im_id('study'),pg_temp.im_id('pet'),2,'void',null,'Wrong study was manually linked')#>>'{study,status}','void','Explicit reason voids current link');
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),pg_temp.im_id('study'),pg_temp.im_id('pet'),3,'correct',pg_temp.im_values(),'Reopen')$$,'PT409',null,'Voided identity cannot be reopened');
select is(jsonb_array_length(list_imaging_history(auth.uid(),pg_temp.im_id('pet'),pg_temp.im_id('study'))->'items'),3,'Void preserves full history');
reset role;
select is((select actor_id from imaging_study_revisions where study_id=pg_temp.im_id('study')and version=1),pg_temp.im_id('actor'),'Actor attributed from live session');
select is((select session_id from imaging_study_revisions where study_id=pg_temp.im_id('study')and version=1),pg_temp.im_id('session'),'Actual session retained');
select throws_ok($$update imaging_study_revisions set reason='rewrite'$$,'23514',null,'Revision immutable');
select throws_ok($$delete from imaging_study_actions$$,'23514',null,'Receipt cannot be deleted');
select throws_ok($$delete from imaging_studies$$,'23514',null,'Root history retained');
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=false where id=pg_temp.im_id('actor');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.im_id('actor'),'session_id',pg_temp.im_id('session'))::text,true);
set local role authenticated;
select throws_ok($$select list_imaging_studies(auth.uid(),pg_temp.im_id('pet'))$$,'42501',null,'Offboarded staff cannot read imaging');
reset role;
select set_config('request.jwt.claims','{}',true);
update profiles set is_active=true where id=pg_temp.im_id('actor');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',pg_temp.im_id('actor'),'session_id',pg_temp.im_id('session'))::text,true);
update pets set archived_at=now()where id=pg_temp.im_id('other_pet');
set local role authenticated;
select throws_ok($$select save_imaging_study(auth.uid(),gen_random_uuid(),gen_random_uuid(),pg_temp.im_id('other_pet'),null,'record',pg_temp.im_values()||'{"external_study_id":"INACTIVE","vendor_patient_id":"INACTIVE"}','')$$,'23514',null,'Inactive patients retain history without new imaging');
reset role;
delete from auth.sessions where id=pg_temp.im_id('session');
set local role authenticated;
select throws_ok($$select list_imaging_studies(auth.uid(),pg_temp.im_id('pet'))$$,'42501',null,'Retired session cannot read imaging');
reset role;
select * from finish();
rollback;
